import{_ as a,C as r,o as n,c as s,j as e,a as i,G as d,a3 as l}from"./chunks/framework.exbasbhr.js";const w=JSON.parse('{"title":"Gestures & Shortcuts","description":"Touch gestures, pen buttons and common shortcut operations in ICC-CE","frontmatter":{"title":"Gestures & Shortcuts","description":"Touch gestures, pen buttons and common shortcut operations in ICC-CE"},"headers":[],"relativePath":"en/guide/gestures-shortcuts.md","filePath":"en/guide/gestures-shortcuts.md"}'),h={name:"en/guide/gestures-shortcuts.md"};function c(u,t,p,g,b,m){const o=r("ArticleMetadata");return n(),s("div",null,[t[0]||(t[0]=e("h1",{id:"gestures-shortcuts",tabindex:"-1"},[i("Gestures & Shortcuts "),e("a",{class:"header-anchor",href:"#gestures-shortcuts","aria-label":'Permalink to "Gestures & Shortcuts"'},"​")],-1)),d(o),t[1]||(t[1]=l('<h2 id="touch-gestures" tabindex="-1">Touch gestures <a class="header-anchor" href="#touch-gestures" aria-label="Permalink to &quot;Touch gestures&quot;">​</a></h2><p>The gesture system can be switched off entirely or enabled item by item in settings.</p><table tabindex="0"><thead><tr><th>Gesture</th><th>Effect</th></tr></thead><tbody><tr><td>One-finger drag</td><td>Draw (in pen mode)</td></tr><tr><td>Two-finger pinch / spread</td><td>Zoom the canvas</td></tr><tr><td>Two-finger drag</td><td>Pan the canvas</td></tr><tr><td>Two-finger rotate</td><td>Rotate the canvas (enable in settings)</td></tr><tr><td>Two-finger tap</td><td>Undo</td></tr><tr><td>Three-finger tap</td><td>Redo</td></tr><tr><td>Multi-finger long press</td><td>Open the quick menu</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Gestures not working</p><p>First confirm the device really supports multi-touch: Device Manager → Human Interface Devices should list a &quot;HID-compliant touch screen&quot;. Some older all-in-one panels have touch drivers that swallow two-finger gestures entirely — update to the vendor&#39;s official driver.</p></div><h2 id="palm-rejection" tabindex="-1">Palm rejection <a class="header-anchor" href="#palm-rejection" aria-label="Permalink to &quot;Palm rejection&quot;">​</a></h2><p>Resting your hand on the screen while writing easily produces stray strokes. ICC-CE offers palm rejection:</p><ul><li>When enabled, contact points with an excessive contact area are ignored</li><li>The threshold is adjustable — the larger the screen, the looser it can be</li><li>On devices with an active stylus you can enable pen-only input to ignore finger input completely</li></ul><h2 id="pen-buttons" tabindex="-1">Pen buttons <a class="header-anchor" href="#pen-buttons" aria-label="Permalink to &quot;Pen buttons&quot;">​</a></h2><p>Supported digital pens usually have one or two barrel buttons that can be mapped to eraser, select, undo and other actions in settings. Many pens also have an eraser tip — just flip the pen over.</p><h2 id="common-operations" tabindex="-1">Common operations <a class="header-anchor" href="#common-operations" aria-label="Permalink to &quot;Common operations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Notes</th></tr></thead><tbody><tr><td>Undo / Redo</td><td>Toolbar buttons, or two-/three-finger tap</td></tr><tr><td>Clear canvas</td><td>Toolbar button; goes on the undo stack, so it can be undone</td></tr><tr><td>Screenshot</td><td>Saves the current screen together with the ink as an image</td></tr><tr><td>Toggle transparent / whiteboard mode</td><td>Toolbar mode button</td></tr><tr><td>Collapse the toolbar</td><td>Toolbar collapse button; drawing is unaffected</td></tr><tr><td>Exit</td><td>Toolbar exit button; triggers one auto-save</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Clear and undo</p><p>Clearing the canvas can be undone, but the undo stack is not kept after the app exits. Take a screenshot or wait for auto-save to finish before quitting if the content matters.</p></div><h2 id="working-with-a-powerpoint-slide-show" tabindex="-1">Working with a PowerPoint slide show <a class="header-anchor" href="#working-with-a-powerpoint-slide-show" aria-label="Permalink to &quot;Working with a PowerPoint slide show&quot;">​</a></h2><p>During a slide show the toolbar gains slide navigation buttons, and changing slides switches the corresponding ink automatically. Slide changes are not part of the undo stack — see the <a href="/website/en/guide/ppt-guide">PowerPoint Guide</a>.</p>',14))])}const v=a(h,[["render",c]]);export{w as __pageData,v as default};
